  const [feedConnected, setFeedConnected] = useState(false);
  const serviceOffset=useRef(0);
  const [timeMode,setTimeMode]=useState(()=>localStorage.getItem('polaris-time-mode')||'accelerated');
  const state = demoState || liveState;
