  const weekFlights=useMemo(()=>allWeekFlights.filter(f=>!f.isCodeshare),[allWeekFlights]);
  const displayWeekFlights=allWeekFlights.filter(f=>traffic==='all'||(traffic==='shared'?f.isCodeshare:!f.isCodeshare));
  const flights=displayWeekFlights.filter(f=>f.status==='airborne'||f.departure?.slice(0,10)===opsClock.toISOString().slice(0,10));
  const aircraft=useMemo(()=>rawAircraft.map(a=>{const tasks=weekFlights.filter(f=>f.aircraftId===a.id),active=tasks.filter(f=>f.status==='airborne'),next=tasks.find(f=>f.status==='scheduled'),previous=tasks.findLast(f=>f.status==='arrived');return {...a,status:active.length>1?'unknown':active.length?'airborne':next?'scheduled':a.status==='airborne'?'idle':a.status,flightId:active.length===1?active[0].id:'',nextFlightId:next?.id||'',location:active.length?'':previous?.destination||next?.origin||a.location};}),[rawAircraft,weekFlights]);
