      <div className="dock-support"><button className="dock-planner" aria-label="直达排班助手" aria-current={tab==='planner'?'page':undefined} title="排班助手" onClick={()=>navigate('planner')}><CalendarPlus size={15}/><span>排班助手</span></button><button className={`icon-button ${tab==='connection'?'active':''}`} aria-label="数据连接" title="数据连接" onClick={()=>navigate('connection')}><Database size={18}/></button><a className="icon-button dock-guide" aria-label="接入指南" title="接入指南" href="/docs/connection-guide.md" target="_blank" rel="noreferrer"><BookOpen size={18}/></a><span className="dock-divider"/><div className="avatar" title="航空运行工作区">AO</div></div>
